using System; using System.Data; using System.Data.SqlClient; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class RegisterPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetSections() { return new { success = true, data = DbHelper.ToDictionaryList(DbHelper.ExecuteDataTable("SELECT SectionID, SectionName FROM Sections WHERE IsActive = 1 ORDER BY SectionName", CommandType.Text)) }; } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetBlocks(int sectionId) { return new { success = true, data = DbHelper.ToDictionaryList(DbHelper.ExecuteDataTable("SELECT BlockID, BlockNumber FROM Blocks WHERE SectionID = @SectionID AND IsActive = 1 ORDER BY BlockNumber", CommandType.Text, new SqlParameter("@SectionID", sectionId))) }; } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetHouses(int blockId) { return new { success = true, data = DbHelper.ToDictionaryList(DbHelper.ExecuteDataTable("SELECT HouseID, HouseNumber FROM Houses WHERE BlockID = @BlockID AND IsActive = 1 ORDER BY HouseNumber", CommandType.Text, new SqlParameter("@BlockID", blockId))) }; } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object RegisterCustomer(string fullName, string phoneNumber, string whatsAppNumber, string email, int sectionId, int blockId, int houseId, string customerType, string serviceName, string preferredSchedule, string latitude, string longitude, string address, string notes) { SecurityHelper.ValidateCsrfOrThrow(); var nextNumber = Convert.ToInt32(DbHelper.ExecuteScalar("SELECT ISNULL(MAX(CustomerID), 0) + 1 FROM Customers", CommandType.Text)); var customerNumber = string.Format("WAMO-{0}-{1}", DateTime.UtcNow.Year, nextNumber.ToString("D6")); DbHelper.ExecuteNonQuery(@"INSERT INTO Customers (CustomerNumber, FullName, PhoneNumber, WhatsAppNumber, Email, SectionID, BlockID, HouseID, CustomerType, ServiceName, PreferredSchedule, Latitude, Longitude, AddressLine, Notes, Status, CreatedDate) VALUES (@CustomerNumber,@FullName,@PhoneNumber,@WhatsAppNumber,@Email,@SectionID,@BlockID,@HouseID,@CustomerType,@ServiceName,@PreferredSchedule,@Latitude,@Longitude,@AddressLine,@Notes,'Pending',GETUTCDATE())", CommandType.Text, new SqlParameter("@CustomerNumber", customerNumber), new SqlParameter("@FullName", fullName ?? string.Empty), new SqlParameter("@PhoneNumber", phoneNumber ?? string.Empty), new SqlParameter("@WhatsAppNumber", (object)whatsAppNumber ?? DBNull.Value), new SqlParameter("@Email", (object)email ?? DBNull.Value), new SqlParameter("@SectionID", sectionId), new SqlParameter("@BlockID", blockId), new SqlParameter("@HouseID", houseId), new SqlParameter("@CustomerType", customerType ?? "Household"), new SqlParameter("@ServiceName", serviceName ?? "Weekly"), new SqlParameter("@PreferredSchedule", preferredSchedule ?? "Weekly"), new SqlParameter("@Latitude", (object)latitude ?? DBNull.Value), new SqlParameter("@Longitude", (object)longitude ?? DBNull.Value), new SqlParameter("@AddressLine", address ?? string.Empty), new SqlParameter("@Notes", (object)notes ?? DBNull.Value)); return new { success = true, customerNumber = customerNumber, message = "Customer registration submitted successfully." }; } } }
